-- Kiteezi Recreational Center - central Supabase schema starter
create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, phone text, role text default 'reception', active boolean default true, created_at timestamptz default now());
create table if not exists roles(id uuid primary key default gen_random_uuid(), name text unique not null, description text);
create table if not exists permissions(id uuid primary key default gen_random_uuid(), code text unique not null, description text);
create table if not exists role_permissions(role_id uuid references roles(id) on delete cascade, permission_id uuid references permissions(id) on delete cascade, primary key(role_id,permission_id));
create table if not exists customers(id uuid primary key default gen_random_uuid(), name text not null, phone text, email text, notes text, created_at timestamptz default now());
create table if not exists services(id uuid primary key default gen_random_uuid(), name text not null, category text, description text, price numeric(12,2), active boolean default true, duration_minutes int, created_at timestamptz default now());
create table if not exists bookings(id uuid primary key default gen_random_uuid(), customer_id uuid references customers(id), service_id uuid references services(id), booking_date date not null, start_time time, people int default 1, source text default 'website', status text default 'pending', payment_status text default 'unpaid', total numeric(12,2) default 0, notes text, created_by uuid references profiles(id), created_at timestamptz default now());
create table if not exists swimming_sessions(id uuid primary key default gen_random_uuid(), booking_id uuid references bookings(id) on delete cascade, session_type text, school_name text, coach_id uuid references profiles(id), attendance_count int, notes text, created_at timestamptz default now());
create table if not exists memberships(id uuid primary key default gen_random_uuid(), customer_id uuid references customers(id), plan_name text, start_date date, end_date date, price numeric(12,2), status text default 'active');
create table if not exists menu_categories(id uuid primary key default gen_random_uuid(), name text unique not null, sort_order int default 0, active boolean default true);
create table if not exists menu_items(id uuid primary key default gen_random_uuid(), category_id uuid references menu_categories(id), name text not null, description text, price numeric(12,2) not null, requires_sides boolean default false, in_stock boolean default true, img_url text, created_at timestamptz default now());
create table if not exists orders(id uuid primary key default gen_random_uuid(), customer_id uuid references customers(id), booking_id uuid references bookings(id), source text default 'pos', status text default 'open', payment_status text default 'unpaid', total numeric(12,2) default 0, created_by uuid references profiles(id), created_at timestamptz default now());
create table if not exists order_items(id uuid primary key default gen_random_uuid(), order_id uuid references orders(id) on delete cascade, menu_item_id uuid references menu_items(id), qty numeric(12,2) not null, unit_price numeric(12,2) not null, notes text);
create table if not exists inventory_items(id uuid primary key default gen_random_uuid(), name text not null, unit text not null, category text, reorder_level numeric(12,2) default 0, active boolean default true);
create table if not exists stock_movements(id uuid primary key default gen_random_uuid(), item_id uuid references inventory_items(id) on delete cascade, quantity numeric(12,2) not null, movement_type text not null, reason text, supplier text, staff_id uuid references profiles(id), created_at timestamptz default now());
create table if not exists events(id uuid primary key default gen_random_uuid(), customer_id uuid references customers(id), event_type text, event_date date, guests int, catering_notes text, customer_equipment text, status text default 'enquiry', total numeric(12,2) default 0, created_at timestamptz default now());
create table if not exists sports(id uuid primary key default gen_random_uuid(), name text unique not null, description text, active boolean default true);
create table if not exists staff_tasks(id uuid primary key default gen_random_uuid(), assigned_to uuid references profiles(id), title text not null, description text, due_date date, status text default 'open', created_at timestamptz default now());
create table if not exists cms_pages(id uuid primary key default gen_random_uuid(), slug text unique not null, title text, content jsonb default '{}'::jsonb, published boolean default true, updated_at timestamptz default now());
create table if not exists media(id uuid primary key default gen_random_uuid(), title text, area text not null, type text, url text not null, sort_order int default 0, active boolean default true, created_at timestamptz default now());
create table if not exists reviews(id uuid primary key default gen_random_uuid(), customer_name text, rating int check(rating between 1 and 5), message text, approved boolean default false, created_at timestamptz default now());
create table if not exists announcements(id uuid primary key default gen_random_uuid(), title text not null, body text, starts_at timestamptz, ends_at timestamptz, published boolean default false);
create table if not exists audit_logs(id uuid primary key default gen_random_uuid(), actor_id uuid references profiles(id), action text not null, entity_type text, entity_id uuid, details jsonb, created_at timestamptz default now());
insert into roles(name,description) values ('owner','Full access'),('general_manager','Operations and approvals'),('reception_manager','Customer operations'),('head_swimming_coach','Swimming operations'),('swimming_coach','Assigned swimming sessions'),('chef','Kitchen and catering'),('barista','Bar operations'),('grounds_cleaning','Facilities tasks'),('website_manager','Website CMS') on conflict(name) do nothing;
insert into services(name,category,description,price,duration_minutes) values ('Public Swimming - Adult','swimming','Daily public swimming',15000,540),('Public Swimming - Child','swimming','Daily public swimming',10000,540),('School Swimming','swimming','Typical school swimming price per child per hour',5000,60),('Swimming Training','swimming','Two-week coaching course; final price configurable',0,60),('Basketball','sports','Basketball booking; price configurable',0,60),('Event & Catering','events','Garden venue with catering',0,180) on conflict do nothing;
